import json, os, sys, urllib.request, urllib.parse, urllib.error
BASE = os.environ.get("HOFJ_BASE_URL", "https://staging.api.hofj.com")
KEY = os.environ.get("API_BEAR_KEY")
if not KEY: sys.exit("API_BEAR_KEY not set")
def call(method, path, params=None, body=None):
    url = BASE + path + ("?" + urllib.parse.urlencode(params) if params else "")
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(url, data=data, method=method)
    req.add_header("Authorization", "Bearer " + KEY)
    if data: req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        raw = e.read().decode(errors="replace")
        try: return e.code, json.loads(raw)
        except Exception: return e.code, raw[:500]
if __name__ == "__main__":
    method, path = sys.argv[1], sys.argv[2]
    params = json.loads(sys.argv[3]) if len(sys.argv) > 3 and sys.argv[3] else None
    body = json.loads(sys.argv[4]) if len(sys.argv) > 4 else None
    st, res = call(method, path, params, body)
    print("HTTP", st, BASE + path)
    print(json.dumps(res, indent=1)[:int(os.environ.get("MAXOUT", "4000"))])
    if os.environ.get("SAVE"): json.dump(res, open(os.environ["SAVE"], "w"), indent=1)
EOF
